class GetDataOperationJobListRequest(PagingParameter, OrderByParameter):
    DataOperationId: Optional[int] = None
    DataOperationName: Optional[str] = None
    OnlyCron: Optional[bool] = None
    OnlyUndeleted: Optional[bool] = None

    def generate_sql_query(self) -> str:
        conditions = []
        if self.DataOperationId is not None:
            conditions.append(f"DataOperationId = {self.DataOperationId}")
        if self.DataOperationName is not None:
            conditions.append(f"DataOperationName = '{self.DataOperationName}'")
        if self.OnlyCron is not None:
            conditions.append(f"OnlyCron = {int(self.OnlyCron)}")
        if self.OnlyUndeleted is not None:
            conditions.append(f"OnlyUndeleted = {int(self.OnlyUndeleted)}")

        where_clause = "WHERE " + " AND ".join(conditions) if conditions else ""
        order_by_clause = self.get_order_by_clause()
        limit_offset_clause = self.get_limit_offset_clause()

        sql_query = f"SELECT * FROM DataOperationJobs {where_clause} {order_by_clause} {limit_offset_clause};"
        return sql_query

    def get_order_by_clause(self) -> str:
        if self.order_by:
            return f"ORDER BY {self.order_by} {self.order_by_direction}"
        return ""

    def get_limit_offset_clause(self) -> str:
        if self.page_size and self.page_number:
            offset = (self.page_number - 1) * self.page_size
            return f"LIMIT {self.page_size} OFFSET {offset}"
        return ""
