        # Reverse the comparison result for less than operation
        for sublist in greater_than_eval:
            if sublist[-1] == "1":
                sublist[-1] = "0"
            elif sublist[-1] == "0":
                sublist[-1] = "1"
        return greater_than_eval

    @classmethod
    def keyword(cls) -> str:
        return "<"
