class Queue:
    def __init__(self, items, size):
        self.queue = items
        self.size = size
        self.head = 0
        self.tail = len(items) % size

    def add(self, item):
        if len(self.queue) < self.size:
            self.queue.append(item)
        else:
            self.queue[self.tail] = item
        self.tail = (self.tail + 1) % self.size
        self.head = (self.tail - len(self.queue)) % self.size

    def pop(self):
        if len(self.queue) > 0:
            self.head = (self.head + 1) % self.size
            return self.queue.pop(0)
        else:
            raise IndexError("Queue is empty")

    def __repr__(self):
        return "{} Head: {}, Tail: {}".format(self.queue, self.head, self.tail)


if __name__ == "__main__":
    queue = Queue(["a", "b", "c"], 4)
    print(queue)  # Output: ['a', 'b', 'c'] Head: 0, Tail: 3
    queue.add("d")
    print(queue)  # Output: ['a', 'b', 'c', 'd'] Head: 0, Tail: 0
    queue.pop()
