import os
import sys
import base64

class NetworkCommunication:
    def __init__(self, fd):
        self.fd = fd

    def send(self, data):
        try:
            os.write(self.fd, data)
        except OSError as e:
            print(f"Error occurred while sending data: {e}")

    def receive(self):
        try:
            data = os.read(self.fd, 8192)
        except OSError:
            data = b''
        sys.stdout.write(base64.b64encode(data))
