import os

def calculate_average_line_count(directory_path):
    data_size = {}
    for file in os.listdir(directory_path):
        if file.endswith('.csv'):
            path = os.path.join(directory_path, file)
            with open(path) as f:
                lines = f.readlines()
                digit = os.path.splitext(file)[0].split('_')[-1]
                if digit not in data_size:
                    data_size[digit] = [len(lines)]
                else:
                    data_size[digit].append(len(lines)

    average_line_count = {}
    for digit in data_size:
        size = data_size[digit]
        average_line_count[digit] = sum(size) / len(size)

    return average_line_count
```

