class CircularDependencyError(Exception):
    pass

def execute_migrations(migrations):
    executed = set()

    def execute(migration):
        if migration.name in executed:
            return
        if migration.name in executing:
            raise CircularDependencyError("Circular dependency detected")
        executing.add(migration.name)
        for dependency in migration.dependencies:
            execute(dependency)
        migration.execute()
        executed.add(migration.name)
        executing.remove(migration.name)

    executing = set()
    for migration in migrations:
        execute(migration)
```

