            # Check room availability for the specified dates
            conflicting_dates = [date for date in room_availability[room_number]['booked_dates']
                                 if check_in_date <= date <= check_out_date]
            if conflicting_dates:
                return jsonify({'message': f'Room {room_number} is not available for the specified dates'})
            else:
                room_availability[room_number]['booked_dates'].append(check_in_date)
                room_availability[room_number]['booked_dates'].append(check_out_date)
                return jsonify({'message': f'Room {room_number} booked for {guest_name} from {check_in_date} to {check_out_date}'})
        else:
            return jsonify({'message': f'Room {room_number} is not available'})
