class TimeoutException(Exception):
    pass

def interruptible_join(thread):
    """Joining a thread without ignoring signal interrupts."""
    while True:
        try:
            thread.join()
            break  # Exit the loop if join is successful
        except KeyboardInterrupt:
            # Handle keyboard interrupt (Ctrl+C) gracefully
            continue  # Continue attempting to join the thread
        except TimeoutException as te:
            raise te  # Propagate TimeoutException if raised during join
